from pathlib import Path
from uuid import uuid4

data = Path('/testbed/data')
files = sorted(
    (p for p in data.iterdir() if p.is_file() and p.suffix == '.csv'),
    key=lambda p: (p.stat().st_size, p.name),
)

staged = []
try:
    for source in files:
        temp = data / f'.csv-rename-{uuid4().hex}.tmp'
        source.rename(temp)
        staged.append(temp)
    for index, temp in enumerate(staged):
        temp.rename(data / f'{index}.csv')
except Exception:
    # Best-effort rollback of files that are still staged.
    for source, temp in zip(files, staged):
        if temp.exists() and not source.exists():
            temp.rename(source)
    raise

for p in sorted(data.glob('*.csv'), key=lambda p: int(p.stem)):
    print(f'{p.name}\t{p.stat().st_size} bytes')
